class Solution {
    public int[] decode(int[] encoded){
        int n=encoded.length+1,first=0;
        for(int value=1;value<=n;value++)first^=value;
        for(int i=1;i<encoded.length;i+=2)first^=encoded[i];
        int[] answer=new int[n];
        answer[0]=first;
        for(int i=0;i<encoded.length;i++)answer[i+1]=answer[i]^encoded[i];
        return answer;
    }
}

code.kotlin:
class Solution {
    fun decode(encoded:IntArray):IntArray{
        val n=encoded.size+1;
        var first=0;
        for(value in 1..n)first=first xor value;
        for(i in 1 until encoded.size step 2)first=first xor encoded[i];
        val answer=IntArray(n);
        answer[0]=first;
        for(i in encoded.indices)answer[i+1]=answer[i] xor encoded[i];
        return answer
    }
}

